using FlexExtractor;
using System.Diagnostics;
static partial class Cases {
 public static void TestMissingLoopbackUncIsBoundedAndRecovers(){var c=Cfg(Fresh());c.WatchRoot=@"\\127.0.0.1\FlexExtractor-Nonexistent-"+Guid.NewGuid().ToString("N");c.WorkerTimeoutSec=2;using var owner=new OwnerLease();var watch=Stopwatch.StartNew();var failed=WorkerRunner.RunAsync(owner,c,"scan",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();Program.Check(failed.Failed>0&&failed.Messages.Count>0&&watch.Elapsed.TotalSeconds<9,"UNC failure not bounded/visible");var local=Cfg(Fresh());Source(local);var recovery=WorkerRunner.RunAsync(owner,local,"scan",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();if(recovery.Copied==0)recovery=WorkerRunner.RunAsync(owner,local,"scan",DateTime.UtcNow,CancellationToken.None).GetAwaiter().GetResult();Program.Check(recovery.Copied==1,"UNC failure prevented subsequent recovery "+string.Join(" | ",recovery.Messages));}
 public static void TestCancelStableCopyWaitsForWorkerBeforeReturn(){var c=Cfg(Fresh());Source(c);c.SizeStableChecks=8;c.SizeStableIntervalMs=1000;using var owner=new OwnerLease();using var cancellation=new CancellationTokenSource(500);var watch=Stopwatch.StartNew();var result=WorkerRunner.RunAsync(owner,c,"scan",DateTime.UtcNow,cancellation.Token).GetAwaiter().GetResult();Program.Check(result.Failed>0&&watch.Elapsed.TotalSeconds<7,"cancel did not terminate worker boundedly");Program.Check(!Directory.Exists(c.DispenseItems[0].SaveFolder)||Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==0,"cancel published XML before validation");Thread.Sleep(300);Program.Check(!Directory.Exists(c.DispenseItems[0].SaveFolder)||Directory.GetFiles(c.DispenseItems[0].SaveFolder,"Request*.xml").Length==0,"cancelled worker wrote later");}
}
